return (function validateInput() {
  const rows = $input.all();
  if (rows.length !== 1) throw Error('Use one contact per operation. Add a loop before this workflow for a contact list.');
  const c = rows[0].json;
  if (!['GBP','USD','EUR'].includes(c.currency) || !Number.isSafeInteger(c.maxSpendMicros) || c.maxSpendMicros < 0 || c.maxSpendMicros > 100000000000 || typeof c.executePaid !== 'boolean') throw Error('Choose currency, an integer spending ceiling, and executePaid true or false.');
  if (!/^[A-Za-z0-9._:-]{1,128}$/.test(c.operationKey || '') || c.operationKey === 'REPLACE_WITH_STABLE_EVENT_ID') throw Error('Set operationKey to a stable unique contact-event ID. Reuse it when retrying; never generate it from the execution ID.');
  const recovering = !!c.recoveryQuoteId;
  if (recovering && !/^[a-f0-9-]{36}$/i.test(c.recoveryQuoteId)) throw Error('Use the original quote ID for recovery.');
  if (!recovering && (typeof c.phone !== 'string' || !c.phone.trim())) throw Error('Enter a phone number you are authorized to query.');
  const allowed = ['basic_line_type','enhanced_line_type','current_carrier','mnp','live_status','sms','whatsapp','telegram'];
  if (!Array.isArray(c.checks) || new Set(c.checks).size !== c.checks.length || c.checks.some(v => !allowed.includes(v))) throw Error('Select supported checks without duplicates.');
  return [{json:{config:c,recovering,input:{phone:c.phone,...(c.defaultCountry ? {default_country:c.defaultCountry} : {}),checks:c.checks}}}];
})();

return (function recoveryResult() {
  const response = $input.first().json, c = $('Validate input').first().json.config;
  if (response.statusCode !== 200 || !['not_started','pending','settled','expired'].includes(response.body?.state)) throw Error('Status unavailable. Retain the original quote and operationKey; no replacement lookup was run.');
  return [{json:{...response.body,operation:{quoteId:c.recoveryQuoteId,idempotencyKey:c.operationKey},instruction:'Recovery never submits execution. Pending: check later. Not started: submit the original quote, maximum and key using the API or Postman. Expired: retained result is unavailable.'}}];
})();

return (function validateQuote() {
  const c = $('Validate input').first().json.config;
  const response = $input.first().json, q = response.body?.quote;
  if (response.statusCode !== 200) throw Error((response.body?.error?.code || 'QUOTE_FAILED') + ' — request ' + (response.body?.error?.requestId || 'unknown'));
  if (!q || !/^[a-f0-9-]{36}$/i.test(q.id) || q.currency !== c.currency || !Number.isSafeInteger(q.maxMicros) || q.maxMicros < 0 || q.maxMicros > c.maxSpendMicros || !Number.isFinite(Date.parse(q.expiresAt)) || Date.parse(q.expiresAt) <= Date.now()) throw Error('Quoted currency, maximum, or expiry needs review. Nothing executed.');
  return [{json:{config:c,quote:q,unavailableChecks:response.body.unavailableChecks,operation:{quoteId:q.id,idempotencyKey:c.operationKey,maxSpendMicros:q.maxMicros,currency:q.currency}}}];
})();

return (function executionResult() {
  const response = $input.first().json, operation = $('Validate quote').first().json.operation;
  if (response.statusCode !== 200 || !response.body?.number) throw Error((response.body?.error?.code || 'EXECUTION_UNRESOLVED') + ' — retain quoteId=' + operation.quoteId + ', idempotencyKey=' + operation.idempotencyKey + ', maxSpendMicros=' + operation.maxSpendMicros + '. Set recoveryQuoteId to this quote and run read-only recovery. Do not create a replacement request.');
  return [{json:{state:'settled',operation,result:response.body}}];
})();

return (function quotePreview() {
  const r = $input.first().json;
  return [{json:{state:'quote_only',quote:r.quote,unavailableChecks:r.unavailableChecks,operation:r.operation,instruction:'No credit used. Review price and availability. Set executePaid=true to run a lookup. Keep the same operationKey for the same contact event.'}}];
})();

return (function contactFields() {
  const r = $input.first().json;
  if (r.state !== 'settled' || !r.result) return [{json:r}];
  const result = r.result;
  const tri = value => typeof value === 'boolean' ? value : null;
  return [{json:{...r,contactUpdate:{
    phone:result.number.e164,number_type:result.number.type ?? null,carrier:result.number.carrier ?? null,
    ported:tri(result.number.ported),sms_supported:tri(result.contact?.sms?.supported),sms_assumed:result.contact?.sms?.assumed ?? false,
    whatsapp_registered:tri(result.contact?.whatsapp?.registered),telegram_registered:tri(result.contact?.telegram?.registered),network_reachable:tri(result.network?.reachable),
    sms_reason:result.contact?.sms?.reason ?? null,whatsapp_reason:result.contact?.whatsapp?.reason ?? null,telegram_reason:result.contact?.telegram?.reason ?? null,network_reason:result.network?.reason ?? null,
    request_id:result.requestId,currency:result.billing?.currency ?? null,charged_micros:result.billing?.chargedMicros ?? null,
  }}}];
})();
